/* your full anime theme here */
}

/* === Monthie Anime Theme === */
body {
  background: linear-gradient(135deg, #0a0a0f, #1a0f1f, #120a18) !important;
  color: #f5eaff !important;
  font-family: "Segoe UI", sans-serif;
}
main {
  background: rgba(20, 10, 30, 0.85) !important;
  backdrop-filter: blur(12px);
  border-radius: 12px;
}
div[class*="message"] {
  background: rgba(40, 20, 60, 0.6) !important;
  border-radius: 12px !important;
  padding: 10px !important;
  margin: 8px 0 !important;
  box-shadow: 0 0 10px rgba(180, 100, 255, 0.2);
}
div[class*="user"] {
  background: rgba(255, 120, 200, 0.25) !important;
  box-shadow: 0 0 12px rgba(255, 120, 200, 0.5);
}
div[class*="assistant"] {
  background: rgba(120, 100, 255, 0.25) !important;
  box-shadow: 0 0 12px rgba(120, 100, 255, 0.5);
}
aside {
  background: rgba(15, 5, 25, 0.95) !important;
  border-right: 1px solid rgba(200, 150, 255, 0.2);
}
button {
  background: rgba(80, 40, 120, 0.6) !important;
  border-radius: 10px !important;
  color: #f0dfff !important;
  transition: 0.2s;
}
button:hover {
  background: rgba(140, 80, 200, 0.8) !important;
  box-shadow: 0 0 10px rgba(200, 150, 255, 0.6);
}
textarea {
  background: rgba(30, 15, 45, 0.9) !important;
  border-radius: 10px !important;
  color: #fff !important;
  border: 1px solid rgba(200, 150, 255, 0.3);
}
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(#ff9cfb, #a78bfa);
  border-radius: 10px;
}
h1, h2, h3 {
  color: #f0d0ff !important;
  text-shadow: 0 0 8px rgba(200, 150, 255, 0.6);
}
/* Background Image */
body {
  background: url("https://images.justwatch.com/backdrop/340746647/s640/Staffel-1.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
}
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(10, 5, 20, 0.75);
  z-index: -1;
}
